def game(A, B):
    if A <= 0 or B <= 0:
        return "Non-drinkers can't play"

    turn = 1
    mike_total = 0
    joe_total = 0

    while True:
        if turn % 2 == 1:
            if mike_total + turn <= A:
                mike_total += turn
            else:
                return "Joe"
        else:
            if joe_total + turn <= B:
                joe_total += turn
            else:
                return "Mike"
        turn += 1
